import sys

def fail():
    sys.exit(1)

def main():
    data = sys.stdin.read().strip().split()
    # need at least 2 tokens for n and a
    if len(data) < 2:
        fail()
    # first two tokens must be integers
    try:
        n = int(data[0])
        a = int(data[1])
    except:
        fail()
    # check ranges for n and a
    if not (1 <= n <= 12):
        fail()
    if not (1 <= a <= 200):
        fail()
    # there must be exactly n more tokens
    if len(data) != 2 + n:
        fail()
    # parse coin values
    coins = []
    try:
        for i in range(n):
            coins.append(int(data[2 + i]))
    except:
        fail()
    # check each coin in range and first is 1
    if coins[0] != 1:
        fail()
    if not (1 <= coins[0] <= 200):
        fail()
    for i in range(1, n):
        if not (1 <= coins[i] <= 200):
            fail()
        if not (coins[i] > coins[i-1]):
            fail()
    # all checks passed
    sys.exit(0)

if __name__ == "__main__":
    main()
